async function resumeExistingLease(spec){
 const root="C:\\workspace\\xenoamess_hoi4_dev";
 const expected="python tools\\rolling_production_queue.py claim "+spec.runId+" --index "+spec.startIndex+" --after "+spec.afterWindow;
 let authorized=false;
 const run=async(command,budget=2500)=>{
  let actual=command;
  if(command===expected){
   if(authorized)throw Error("Existing owner may be resumed only once");
   actual="python -X utf8 runtime\\reconcile-low-auth-image-20261025.py --guard";
  }else if(!authorized)throw Error("Resume guard must complete before queue operations");
  let r=await tools.exec_command({cmd:actual,shell:"cmd.exe",login:false,workdir:root,max_output_tokens:budget});
  let output=r.output||"";
  while(r.session_id){r=await tools.write_stdin({session_id:r.session_id,chars:"",yield_time_ms:1000,max_output_tokens:budget});output+=r.output||"";}
  if(r.exit_code!==0)throw Error(JSON.stringify({...r,output}));
  if(command===expected){if(!JSON.parse(output).resume_existing_owner_verified)throw Error("Guard refused");authorized=true;}
  const result={...r,output};
  if(!actual.includes("production_transport_preview.py"))store(spec.runId+"_last_local_result",{command:actual,result,observed_at_utc:new Date().toISOString()});
  return result;
 };
 const queue=eval("("+load("logical_queue_source")+")");
 const window=eval("("+load("bounded_window_source")+")");
 return await queue(spec,{run,producer:(plan,options)=>window(plan,options)});
}
const remainingSeconds=Math.floor((Date.parse("2026-10-25T02:59:30.009Z")-Date.now())/1000);
if(remainingSeconds<=0)throw Error("Original v5 deadline reached; do not reset it");
await resumeExistingLease({runId:"resume-20261025-large-logical-queue-v5",startIndex:554,
 afterWindow:"resume-20261025-large-logical-queue-v5-window553-import-reconciled",
 maxCalls:50,maxPreviewBytes:6553600,maxRunSeconds:remainingSeconds});
